exports.init = (params, rng) => {
  const vol = params.objectVolume ?? 0.001;
  const H = Math.pow(vol, 1/3) * 8;
  const SURFACE_Y = 5;
  // Start centered at the waterline so fluidDensity immediately matters (sub=0.5)
  const y0 = SURFACE_Y;
  const sub0 = 0.5;
  const objRho = params.objectDensity ?? 917;
  const fluidRho = params.fluidDensity ?? 1000;
  const g = params.gravity ?? 9.81;
  const mass = objRho * vol;
  const Vdisp0 = sub0 * vol;
  const buoy0 = fluidRho * Vdisp0 * g;
  const weight0 = mass * g;
  return {
    y: y0,
    vy: 0,
    H: H,
    vol: vol,
    sub: sub0,
    buoy: buoy0,
    weight: weight0,
    dispWeight: buoy0,
    isFloating: 1,
    time: 0
  };
};
exports.step = (state, params, rng) => {
  const dt = 0.04;
  const SURFACE_Y = 5;
  const vol = params.objectVolume ?? 0.001;
  const objRho = params.objectDensity ?? 917;
  const fluidRho = params.fluidDensity ?? 1000;
  const g = params.gravity ?? 9.81;
  const H = Math.pow(vol, 1/3) * 8;
  let y = state.y;
  let vy = state.vy;
  const bottom = y - H/2;
  const top = y + H/2;
  let sub = 0;
  if (bottom >= SURFACE_Y) sub = 0;
  else if (top <= SURFACE_Y) sub = 1;
  else sub = (SURFACE_Y - bottom) / H;
  sub = Math.max(0, Math.min(1, sub));
  const mass = objRho * vol;
  const weight = mass * g;
  const Vdisp = sub * vol;
  const buoy = fluidRho * Vdisp * g;
  const net = buoy - weight;
  const dragCoeff = sub > 0 ? 2.5 : 0.3;
  const drag = -dragCoeff * vy - (0.8 + sub * 1.2) * vy * Math.abs(vy);
  const a = (net + drag) / mass;
  vy += a * dt;
  if (vy > 8) vy = 8;
  if (vy < -8) vy = -8;
  y += vy * dt;
  if (y - H/2 < 0) {
    y = H/2;
    if (vy < 0) vy = 0;
  }
  if (y + H/2 > 10) {
    y = 10 - H/2;
    if (vy > 0) vy = 0;
  }
  const bottom2 = y - H/2;
  const top2 = y + H/2;
  let sub2 = 0;
  if (bottom2 >= SURFACE_Y) sub2 = 0;
  else if (top2 <= SURFACE_Y) sub2 = 1;
  else sub2 = (SURFACE_Y - bottom2) / H;
  sub2 = Math.max(0, Math.min(1, sub2));
  const Vdisp2 = sub2 * vol;
  const buoy2 = fluidRho * Vdisp2 * g;
  const dispWeight2 = fluidRho * Vdisp2 * g;
  const atBottom = (y - H/2 <= 0.001);
  let isFloating = 0;
  if (atBottom) {
    isFloating = 0;
  } else if (sub2 >= 0.999) {
    if (weight <= buoy2 + 1e-6) isFloating = 1;
    else isFloating = 0;
  } else if (sub2 > 0.01) {
    isFloating = 1;
  } else {
    isFloating = 0;
  }
  return {
    y: y,
    vy: vy,
    H: H,
    vol: vol,
    sub: sub2,
    buoy: buoy2,
    weight: weight,
    dispWeight: dispWeight2,
    isFloating: isFloating,
    time: state.time + dt
  };
};
exports.observe = (state, params) => {
  const ratio = state.dispWeight > 1e-9 ? state.buoy / state.dispWeight : 1;
  return {
    submerged_fraction: state.sub,
    is_floating: state.isFloating,
    buoyant_force_to_displaced_weight_ratio: ratio,
    block_depth: state.y,
    buoyant_force: state.buoy
  };
};
exports.view = (state, params) => {
  const BOUNDS_H = 10;
  const toScreenY = (physY) => BOUNDS_H - physY;
  const bounds = { x: 0, y: 0, w: 10, h: 10 };
  const waterScreenY = 9;
  const waterRadius = 4;
  const iceScreenY = toScreenY(state.y);
  const iceRadius = state.H / 2;
  const atBottom = (state.y - state.H/2 <= 0.01);
  let iceColor = '#E0F4FF';
  if (atBottom) iceColor = '#FF6B6B';
  else if (state.sub > 0.01) iceColor = '#A0E8FF';
  else iceColor = '#D0E8FF';
  const bodies = [
    { id: 'water', x: 5, y: waterScreenY, radius: waterRadius, color: '#4A90E2' },
    { id: 'ice', x: 5, y: iceScreenY, radius: iceRadius, color: iceColor }
  ];
  return { kind: 'bodies', bounds: bounds, bodies: bodies };
};
